{"path":"assets/css/styles.css","content":"/* Minimal poetic UI for holistic practice — split diagonal layout */
:root{
  --bg:#FAFFFD;
  --muted:#6B6B6B;
  --accent:#00796B;
  --accent-2:#004D40;
  --surface:#FFFFFF;
  --glass:rgba(255,255,255,0.6);
  --radius:18px;
  --max-width:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#032;line-height:1.45;background:linear-gradient(180deg,var(--bg),#F2FFF7 60%);}
.container{max-width:var(--max-width);margin:0 auto;padding:28px}
.site-header{position:sticky;top:0;background:linear-gradient(180deg,rgba(255,255,255,0.8),transparent);backdrop-filter:blur(4px);z-index:20}
.site-header .container{display:flex;align-items:center;justify-content:space-between;padding:14px 28px}
.brand{font-weight:700;color:var(--accent-2);text-decoration:none;font-size:1.05rem}
.nav-list{list-style:none;margin:0;padding:0;display:flex;gap:14px;align-items:center}
.nav-list a{color:var(--muted);text-decoration:none;padding:6px 10px;border-radius:8px}
.nav-list a:hover{background:var(--glass)}
.cta, .primary{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#fff;padding:8px 14px;border-radius:12px;text-decoration:none}
.primary.large{padding:12px 20px;font-size:1.05rem}
.nav-toggle{display:none;background:transparent;border:1px solid rgba(0,0,0,0.06);padding:8px;border-radius:8px}

/* Split diagonal hero */
.layout-split main{display:block}
.split-diagonal{display:flex;min-height:60vh;margin:28px 0;border-radius:20px;overflow:hidden;position:relative}
.split-diagonal .panel{flex:1;display:flex;align-items:center}
.split-diagonal .panel-left{background:linear-gradient(135deg,#F0FFF9,#E8F9F3);padding:36px}
.split-diagonal .panel-right{background:transparent;padding:36px}
.split-diagonal .pattern{position:absolute;inset:0;background-image:url('assets/img/pattern.svg');background-repeat:repeat;opacity:0.12;mix-blend-mode:multiply}
.hero-copy{position:relative;z-index:2}
.hero h1{margin:0;font-size:2.1rem;color:var(--accent-2)}
.lead{font-weight:600;color:var(--accent);margin-top:8px}
.poem{font-style:italic;color:var(--muted);margin-top:12px}
.hero-visual{display:flex;align-items:center;justify-content:center}
.hero-svg{width:100%;height:100%;max-width:520px;border-radius:18px;box-shadow:0 10px 30px rgba(0,0,0,0.06)}

/* Diagnostic */
.diagnostic{padding:48px 28px}
.diagnostic h2{font-size:1.35rem;color:var(--accent-2)}
.diagnostic-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px;margin-top:18px}
.card{background:var(--surface);padding:18px;border-radius:14px;box-shadow:0 6px 18px rgba(6,30,20,0.04)}
.card h3{margin-top:0;color:var(--accent-2)}

/* Plan with alternate diagonal */
.split-diagonal-alt{display:flex;margin:28px 0;border-radius:18px;overflow:hidden}
.split-diagonal-alt .panel{flex:1;padding:28px}
.split-diagonal-alt .panel-left{background:linear-gradient(90deg,#F7FFF8,#F0FBF9)}
.split-diagonal-alt .panel-right{background:linear-gradient(180deg,#00695C,#004D40);color:white;display:flex;align-items:center}
.split-diagonal-alt .icon{display:block;margin-bottom:12px}
.tagline{font-weight:600}
.steps{margin:8px 0 0 0;padding-left:18px}
.steps li{margin-bottom:8px}

/* Micro-habits */
.micro-habits{padding:36px 28px}
.habits{list-style:none;padding:0;margin:12px 0 0 0}
.habits li{background:linear-gradient(90deg,rgba(0,121,107,0.04),transparent);padding:12px;border-radius:12px;margin-bottom:8px}

/* Pricing */
.pricing{margin:28px 0}
.price-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:16px;margin-top:18px}
.price-card{background:var(--surface);padding:18px;border-radius:12px;box-shadow:0 10px 30px rgba(0,0,0,0.04)}
.price{font-weight:700;color:var(--accent-2)}
.disclaimer{font-size:0.85rem;color:var(--muted)}

/* CTA */
.cta{padding:36px 28px;text-align:center}
.practitioner{font-size:0.92rem;color:var(--muted);margin-top:8px}

/* Footer */
.site-footer{padding:28px 0;background:transparent}
.footer-nav{display:flex;gap:12px;justify-content:center;margin-bottom:8px}
.small{color:var(--muted);text-align:center}

/* Responsive */
@media(max-width:900px){
  .split-diagonal, .split-diagonal-alt{flex-direction:column}
  .nav-list{display:none}
  .nav-toggle{display:inline-block}
  .nav[aria-expanded="true"] .nav-list{display:flex;flex-direction:column;background:var(--surface);position:absolute;right:20px;top:64px;padding:12px;border-radius:10px;box-shadow:0 10px 30px rgba(0,0,0,0.08)}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Minimal interactivity: nav toggle, set year, smooth scroll for hash links
  var btn = document.querySelector('.nav-toggle');
  var nav = document.querySelector('nav');
  var navList = document.getElementById('nav-list');
  if(btn){
    btn.addEventListener('click', function(){
      var expanded = btn.getAttribute('aria-expanded') === 'true';
      btn.setAttribute('aria-expanded', String(!expanded));
      if(!expanded){
        nav.setAttribute('aria-expanded','true');
        navList.style.display = 'flex';
      } else {
        nav.setAttribute('aria-expanded','false');
        navList.style.display = '';
      }
    });
  }

  // Set year in footer
  var y = new Date().getFullYear();
  var yearEl = document.getElementById('year');
  if(yearEl) yearEl.textContent = y;

  // Smooth scroll for internal links
  document.addEventListener('click', function(e){
    var a = e.target.closest('a');
    if(!a) return;
    var href = a.getAttribute('href');
    if(href && href.startsWith('#')){
      e.preventDefault();
      var target = document.querySelector(href);
      if(target) target.scrollIntoView({behavior:'smooth',block:'start'});
    }
  });

  // Lightweight analytics stub for CTA clicks
  var ctas = document.querySelectorAll('a.cta, a.primary');
  ctas.forEach(function(el){
    el.addEventListener('click', function(){
      try{console.info('CTA clicked:', el.textContent);}catch(e){}
    });
  });
})();"} 
